create or replace TABLE SZD_PRODUCTION.CORE_REL.T_BROKER_REPORT (
	MOVEMENT_REF_NUMBER VARCHAR(250) NOT NULL COMMENT 'This is a customs identification number that’s created each time a declaration is submitted\n            The movement reference number for importing or exporting goods. The number generated is bespoke, allowing your goods to be uniquely linked to you. As such, it forms an important part of the audit process for your declarations.',
	AUTHORITY_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the country of the customs auhtority.',
	IMPORTER_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the importer.',
	IMPORTER_DECLARANT_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the importer who makes the declaration.',
	BROKER_DECLARANT_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the broker who makes the declaration..',
	CUSTOMS_DECLARATION_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the customs declaration type.',
	EXPORT_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the country where the goods leave the EU.',
	CDS_ACCEPTANCE_DT DATE NOT NULL COMMENT 'This is the date when the goods have arrived at the import location.',
	CDS_ACCEPTANCE_TMSP TIMESTAMP_TZ(9) COMMENT 'Descriptive Attribute - This is the date and time when the goods have arrived at the import location.',
	CDS_CLEARANCE_DT DATE NOT NULL COMMENT 'This is only the date part of the clearance date and time (see also CDS_CLEARANCE_TMSP).',
	CDS_CLEARANCE_TMSP TIMESTAMP_TZ(9) COMMENT 'Descriptive Attribute - The CDS clearance date is  the clearance date of the supplementary declaration when HRMC considers the declaration finalised and all duties and taxes are accounted for.',
	ACCEPTANCE_TMSP TIMESTAMP_TZ(9) COMMENT 'The Acceptance is the date and time of the frontier declarations clearance.',
	TRADER_REFERENCE VARCHAR(250) NOT NULL COMMENT 'Descriptive Attribute - This is a reference assigned by the declarant for the goods covered by the declaration.',
	CONSIGNOR_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the consignor.',
	CONSIGNOR_NAME VARCHAR(100) COMMENT 'Descriptive Attribute - Textual data  of the consignor''s name.It is the name stored in the broker system.',
	FIRST_DEFERMENT VARCHAR(250) COMMENT 'Descriptive Attribute - The first Deferment Approval Number to identify the deferment account to  which revenue is to be debited.',
	GOODS_LOCATION VARCHAR(250) COMMENT 'Descriptive Attribute - The location where the goods are held at the time of making the declaration.',
	TRADE_TERMS VARCHAR(250) COMMENT 'Descriptive Attribute - International Commercial Term;It defines the responsibilities of exporters and importers in the arrangement of shipments and the transfer of liability involved at various stages of the transaction.',
	TRADE_TERMS_LOCATION VARCHAR(250) COMMENT 'Descriptive Attribute - Location of port where the terms apply to.',
	DECLARATION_UCR VARCHAR(250) COMMENT 'Descriptive Attribute - This is a unique consignment reference for the goods covered by the declaration. The reference can be used to identify the entry for amendment or cancellation and is used for inventory linking. On a declaration the UCR may be a reference allocated by a forwarder or one chosen by the declarant, possibly allocated by the exporter, seller, buyer or importer.',
	TOTAL_PACKAGES_CNT NUMBER(38,0) NOT NULL COMMENT 'Fact - additive - Total count of all packages of a declaration.',
	EXCISE_PAYMENT_AMOUNT_VAL NUMBER(38,5) COMMENT 'Fact - additive - It is the excise payment amount for the whole shipment.',
	VALUE_FOR_DUTY_VAL NUMBER(38,5) COMMENT 'Fact - additive - The total value of the shipment for purposes of Duty. When we say one shipment,the MRN will differ between the SFD and the SDI as they are essentially two separate entries in the system, but the trader ref should be the same for both',
	DUTY_PAYMENT_AMOUNT_VAL NUMBER(38,5) COMMENT 'Fact - additive - The duty for the whole shipment.',
	DUTY_TAX_ASSESSED_AMOUNT_VAL NUMBER(38,5) COMMENT 'Fact - additive - The assessed duty for the whole shipment. Normally this should be the same as the duty payment amount.',
	VALUE_FOR_VAT_VAL NUMBER(38,5) COMMENT 'Fact - additive - The total value of the whole Shipement.',
	VAT_PAYMENT_AMOUNT_VAL NUMBER(38,5) COMMENT 'Fact - additive - The broker report contains information of a bunch of customs declarations. The broker report is based on a report from an importer (BEI report from LexI or WWT report from OWIM or Lidl Foundation) and contains informationen that are ideally identical to the report from the customs authority.',
	VAT_TAX_ASSESSED_AMOUNT_VAL NUMBER(38,5) COMMENT 'Fact - additive -  It means how much VAT should be paid for the whole shipment.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_SRC_FILE_NAME VARCHAR(500) COMMENT 'Contains the name(s) of the input file(s) that delivered the record. It can be either the full path of the BLOG storage or the shortened file path',
	DWH_SRC_1_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The extraction timestamp of the record from the source',
	constraint PK_BROKER_REPORT primary key (MOVEMENT_REF_NUMBER, TRADER_REFERENCE)
)COMMENT='Entity - Transactional Events - Snapshot - The broker report contains information of a bunch of customs declarations. The broker report is based on a report from an importer (BEI report from LexI or WWT report from OWIM or Lidl Foundation) and contains informationen that are ideally identical to the report from the customs authority. - Source - Excel-Report from Broker (per Mail)'
;